import{_ as e,C as i,c as n,o as r,a6 as s,G as l}from"./chunks/framework.BY05barL.js";const t="/ucasal-ssoo-estudio/assets/9-spooling.ChplvO6k.png",b=JSON.parse('{"title":"Spooling","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/spooling.md","filePath":"unidad1/spooling.md"}'),p={name:"unidad1/spooling.md"};function c(d,a,u,m,h,g){const o=i("SpoolingDemo");return r(),n("div",null,[a[0]||(a[0]=s('<h1 id="spooling" tabindex="-1">Spooling <a class="header-anchor" href="#spooling" aria-label="Permalink to &quot;Spooling&quot;">​</a></h1><h3 id="simultaneous-peripheral-operation-on-line" tabindex="-1">Simultaneous Peripheral Operation On-Line <a class="header-anchor" href="#simultaneous-peripheral-operation-on-line" aria-label="Permalink to &quot;Simultaneous Peripheral Operation On-Line&quot;">​</a></h3><p>El spooling es una <strong>técnica</strong> del sistema operativo para manejar dispositivos dedicados, como la impresora.</p><h2 id="¿por-que-hace-falta" tabindex="-1">¿Por qué hace falta? <a class="header-anchor" href="#¿por-que-hace-falta" aria-label="Permalink to &quot;¿Por qué hace falta?&quot;">​</a></h2><p>Una impresora no se puede compartir al mismo tiempo: si dos procesos imprimieran a la vez, sus páginas saldrían mezcladas. Sin spooling, mientras un proceso usa la impresora, los demás que quieren imprimir quedan bloqueados esperando.</p><h2 id="como-funciona" tabindex="-1">Cómo funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Cómo funciona&quot;">​</a></h2><ul><li>Cada proceso escribe su trabajo en un <strong>directorio de spool en el disco</strong>. Es rápido, y el proceso sigue ejecutando.</li><li>Un <strong>daemon</strong>, el único proceso autorizado a usar la impresora, toma los trabajos del directorio en orden y los imprime.</li></ul><p><img src="'+t+'" alt="Spooling"></p><h2 id="origen" tabindex="-1">Origen <a class="header-anchor" href="#origen" aria-label="Permalink to &quot;Origen&quot;">​</a></h2><p>Surgió en la tercera generación: las tarjetas se leían al disco apenas llegaban a la sala de cómputo, mientras la CPU ejecutaba otros trabajos. También se usó para la salida. Hoy se usa sobre todo para imprimir, y la misma idea aparece en el correo electrónico.</p><h2 id="simulacion" tabindex="-1">Simulación <a class="header-anchor" href="#simulacion" aria-label="Permalink to &quot;Simulación&quot;">​</a></h2><p>Compará los dos modos: sin spooling, B y C quedan bloqueados esperando la impresora; con spooling, siguen ejecutando.</p>',12)),l(o)])}const f=e(p,[["render",c]]);export{b as __pageData,f as default};
